const COLORS={"North America":"#1f5b8f","Europe":"#72a8d4","Asia":"#2a9d8f","Other":"#75658e","Gold Price (rhs)":"#c49332"};
const LABELS={"North America":"北美","Europe":"欧洲","Asia":"亚洲","Other":"其他","Gold Price (rhs)":"黄金价格（右侧）"};
let flowState={unit:'usd',freq:'Weekly'}, holdState={unit:'tonnes',freq:'Weekly'}, tableState={period:'Weekly',date:'2026-08-14'};
