function dates(vals){return vals.map(p=>new Date(p[0]));}
function seriesData(vals, div=1){return vals.map(p=>p[1]==null?null:p[1]/div);}
function rangePaddingDays(frequency){
  return {Yearly:183,Quarterly:46,Monthly:16,Weekly:4}[frequency]||4;
}
function paddedRangeEnd(latestDate,frequency){
  return new Date(Number(latestDate)+rangePaddingDays(frequency)*86400000);
}
function paddedFullHistoryEnd(earliestDate,latestDate,frequency){
  const spanDays=(Number(latestDate)-Number(earliestDate))/86400000;
  const visualPadding=Math.max(rangePaddingDays(frequency),Math.ceil(spanDays*.008));
  return new Date(Number(latestDate)+visualPadding*86400000);
}
function recentTwoYearRange(latestDate,frequency){
  const end=new Date(latestDate);
  const start=new Date(end);
  start.setFullYear(start.getFullYear()-2);
  return [start,paddedRangeEnd(latestDate,frequency)];
}
function commonLayout(ytitle, isFlow){
  return {
    paper_bgcolor:'#fff',plot_bgcolor:'#fff',showlegend:false,hovermode:'x unified',dragmode:'zoom',
    margin:{l:52,r:62,t:12,b:80},
    font:{family:'Arial, Microsoft YaHei, sans-serif',size:14,color:'#111'},
    xaxis:{type:'date',showgrid:false,showline:true,linecolor:'#777',linewidth:1,ticks:'outside',ticklen:10,tickcolor:'#777',
      tickformat:'%Y年%-m月',unifiedhovertitle:{text:'<b>%{x|%Y年%-m月%-d日}</b>'},
      rangeslider:{visible:true,thickness:.105,bgcolor:'#eaf0f7',bordercolor:'#c7d3e0',borderwidth:1},
      rangeselector:{visible:false},fixedrange:false},
    yaxis:{title:'',showgrid:false,gridcolor:'#e4eaf1',griddash:'solid',zeroline:isFlow,zerolinecolor:'#777',zerolinewidth:1,tickformat:isFlow?'.1f':',.0f'},
    yaxis2:{title:'',overlaying:'y',side:'right',showgrid:false,zeroline:false,tickformat:',.0f'},
    hoverlabel:{bgcolor:'#ffffff',bordercolor:'#6f8093',font:{family:'Microsoft YaHei, PingFang SC, Arial',size:12,color:'#18314f'},align:'left'},
    barmode:isFlow?'relative':undefined,bargap:isFlow?.1:undefined
  }
}
function renderLegend(containerId, chartId){
  const c=document.getElementById(containerId);c.innerHTML='';
  const items=[['North America','#1f5b8f'],['Europe','#72a8d4'],['Asia','#2a9d8f'],['Other','#75658e'],['Gold Price (rhs)','#c49332']];
  items.forEach((it,i)=>{const traceIndex=i===4?5:i;const b=document.createElement('button');b.type='button';b.className='legend-box';b.style.setProperty('--legend-color',it[1]);b.textContent=LABELS[it[0]];b.onclick=()=>{b.classList.toggle('off');const vis=b.classList.contains('off')?'legendonly':true;Plotly.restyle(chartId,{visible:vis},[traceIndex]);};c.appendChild(b);});
}
function renderFlow(){
  const arr=FLOW_DATA.data[flowState.freq].series[flowState.unit];
  const div=flowState.unit==='usd'?1e8:1;
  const valueUnit=flowState.unit==='usd'?'亿美元':'吨';
  document.getElementById('flowLeftLabel').textContent=flowState.unit==='usd'?'基金流量（亿美元）':'需求（吨）';
  document.getElementById('flowDataAsOf').textContent='数据截至 '+cnDate(FLOW_DATA.asOfDate);
  const totals=new Map();
  arr.slice(0,4).forEach(s=>s.data.forEach(p=>totals.set(p[0],(totals.get(p[0])||0)+(p[1]==null?0:p[1]/div))));
  const traces=arr.slice(0,4).map(s=>({
    x:dates(s.data),y:seriesData(s.data,div),name:LABELS[s.name]||s.name,
    type:'bar',marker:{color:COLORS[s.name]},
    hovertemplate:(LABELS[s.name]||s.name)+'：%{y:,.2f} '+valueUnit+'<extra></extra>'
  }));
  const totalDates=arr[0].data.map(p=>new Date(p[0]));
  traces.push({x:totalDates,y:arr[0].data.map(p=>totals.get(p[0])),name:'总量',type:'scatter',mode:'lines',line:{color:'rgba(0,0,0,0)',width:0},showlegend:false,hovertemplate:'<b>总量：%{y:,.2f} '+valueUnit+'</b><extra></extra>'});
  const gold=arr[4];
  traces.push({x:dates(gold.data),y:seriesData(gold.data),name:'黄金价格（右侧）',type:'scatter',mode:'lines',yaxis:'y2',line:{color:'#c49332',width:3},hovertemplate:'黄金：%{y:,.2f} 美元/盎司<extra></extra>'});
  const lay=commonLayout('',true);lay.height=455;
  const latestFlowDate=Math.max(...arr.flatMap(s=>s.data.map(p=>p[0])));
  const earliestFlowDate=Math.min(...arr.flatMap(s=>s.data.map(p=>p[0])));
  const latestFlowPadded=paddedRangeEnd(latestFlowDate,flowState.freq);
  lay.xaxis.range=recentTwoYearRange(latestFlowDate,flowState.freq);
  lay.xaxis.rangeslider.range=[new Date(earliestFlowDate),latestFlowPadded];
  traces.forEach(t=>Object.keys(t).forEach(k=>{if(t[k]===undefined)delete t[k];}));
  Object.keys(lay).forEach(k=>{if(lay[k]===undefined)delete lay[k];});
  Plotly.react('flowChart',traces,lay,{responsive:true,displayModeBar:false});renderLegend('flowLegend','flowChart');
}
function renderHold(){
  const obj=HOLD_DATA.data[holdState.freq][holdState.unit], cols=obj.columns, rows=obj.set, div=holdState.unit==='usd'?1e8:1;
  const valueUnit=holdState.unit==='usd'?'亿美元':'吨';
  document.getElementById('holdLeftLabel').textContent=holdState.unit==='usd'?'资产管理规模（亿美元）':'持有量（吨）';
  document.getElementById('holdDataAsOf').textContent='数据截至 '+cnDate(HOLD_DATA.asOfDate);
  const xs=rows.map(r=>new Date(r[0]));
  const traces=[];
  for(let i=1;i<=4;i++) traces.push({x:xs,y:rows.map(r=>r[i]==null?null:r[i]/div),name:LABELS[cols[i]]||cols[i],type:'scatter',mode:'lines',stackgroup:'one',line:{width:.8,color:COLORS[cols[i]]},fillcolor:COLORS[cols[i]],hovertemplate:(LABELS[cols[i]]||cols[i])+'：%{y:,.1f} '+valueUnit+'<extra></extra>'});
  traces.push({x:xs,y:rows.map(r=>[1,2,3,4].reduce((sum,i)=>sum+(r[i]==null?0:r[i]/div),0)),name:'总量',type:'scatter',mode:'lines',line:{color:'rgba(0,0,0,0)',width:0},showlegend:false,hovertemplate:'<b>总量：%{y:,.1f} '+valueUnit+'</b><extra></extra>'});
  traces.push({x:xs,y:rows.map(r=>r[5]),name:'黄金价格（右侧）',type:'scatter',mode:'lines',yaxis:'y2',line:{color:'#c49332',width:3},hovertemplate:'黄金：%{y:,.2f} 美元/盎司<extra></extra>'});
  const lay=commonLayout('',false);lay.height=455;lay.yaxis.tickformat=',.0f';
  const earliestHoldDate=Math.min(...rows.map(r=>r[0]));
  const latestHoldDate=Math.max(...rows.map(r=>r[0]));
  const latestHoldPadded=paddedFullHistoryEnd(earliestHoldDate,latestHoldDate,holdState.freq);
  lay.xaxis.range=[new Date(earliestHoldDate),latestHoldPadded];
  lay.xaxis.rangeslider.range=[new Date(earliestHoldDate),latestHoldPadded];
  traces.forEach(t=>Object.keys(t).forEach(k=>{if(t[k]===undefined)delete t[k];}));
  Object.keys(lay).forEach(k=>{if(lay[k]===undefined)delete lay[k];});
  Plotly.react('holdChart',traces,lay,{responsive:true,displayModeBar:false});renderLegend('holdLegend','holdChart');
}
function bindToggle(id,state,key,renderer){document.getElementById(id).addEventListener('click',e=>{const b=e.target.closest('button[data-v]');if(!b)return;state[key]=b.dataset.v;[...b.parentElement.children].forEach(x=>x.classList.toggle('active',x===b));renderer();});}
