function cleanHeader(h){h=h.replace(/<br\s*\/?\s*>/gi,' ').replace(/\s+/g,' ').trim();return h.replace('AUM (bn)','资产管理规模（亿美元）').replace('Fund Flows (US$mn)','基金流量（百万美元）').replace('Holdings (tonnes)','持仓量（公吨）').replace('Demand (tonnes)','需求（吨）').replace('Demand (% of holdings)','需求（占总持仓比例）').replace(/^Region$/,'区域').replace(/^Country$/,'国家').replace(/^Fund$/,'基金').replace(/^Name$/,'名称');}
function fmtNum(v,dec=1){if(v===''||v==null)return '';const n=Number(v);if(!Number.isFinite(n))return v;return n.toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec});}
const tableSort={regional:{col:null,dir:null},countries:{col:null,dir:null}};
function firstLabel(v,key){
  let text=String(v??'').replace('North America','北美').replace('Europe','欧洲').replace('Asia','亚洲').replace('Other','其它').replace('Total','总计').replace('Global inflows / Positive Demand','全球总流入/正需求').replace('Global outflows / Negative Demand','全球总流出/负需求');
  if(key==='countries' && COUNTRY_ZH[text]) text=COUNTRY_ZH[text];
  return text;
}
function compareTableValues(a,b,col,key,dir){
  let av=a[col], bv=b[col];
  let cmp=0;
  if(col===0){
    av=firstLabel(av,key); bv=firstLabel(bv,key);
    cmp=String(av).localeCompare(String(bv),'zh-CN',{numeric:true,sensitivity:'base'});
  }else{
    const an=(av===''||av==null)?null:Number(av), bn=(bv===''||bv==null)?null:Number(bv);
    if(an==null && bn==null) cmp=0;
    else if(an==null) cmp=1;
    else if(bn==null) cmp=-1;
    else cmp=an-bn;
  }
  return dir==='asc'?cmp:-cmp;
}
function renderDataTable(id,key){
  const block=currentTable.data[key][tableState.period]; if(!block)return;
  const data=block.data, cols=data.columns; const t=document.getElementById(id);
  const st=tableSort[key] || (tableSort[key]={col:null,dir:null});
  let h='<colgroup>';
  cols.forEach((c,i)=>{let w=(key==='regional'||key==='countries')?(i===0?27:14.6):(i===0?34:(i===1?16:12.5));h+=`<col style="width:${w}%">`;});
  h+='</colgroup><thead><tr>';
  cols.forEach((c,i)=>{
    const up=st.col===i&&st.dir==='asc'?' active':'';
    const down=st.col===i&&st.dir==='desc'?' active':'';
    h+=`<th class="sortable" data-col="${i}" title="点击排序">${cleanHeader(c)}<span class="sort"><span class="up${up}">▲</span><span class="down${down}">▼</span></span></th>`;
  });
  h+='</tr></thead><tbody>';

  const rows=Object.keys(data).filter(k=>k!=='columns').sort((a,b)=>Number(a)-Number(b)).map(k=>data[k]);
  const pinned=[]; const regular=[];
  rows.forEach(r=>{
    const first=r[0]||'';
    if(first==='Total' || /Global inflows|Global outflows/.test(first)) pinned.push(r); else regular.push(r);
  });
  if(st.col!==null && st.dir) regular.sort((a,b)=>compareTableValues(a,b,st.col,key,st.dir));

  [...regular,...pinned].forEach(r=>{
    const first=r[0]||'';const total=first==='Total';const global=/Global inflows|Global outflows/.test(first);
    h+='<tr class="'+(total?'total-row ':global?'global-row ':'')+'">';
    r.forEach((v,i)=>{
      let text=v,cls=i===0?'':'num';
      if(i>0 && v!==''){
        const n=Number(v); const isPct=i===cols.length-1; const displayN=/AUM\s*<br\s*\/?\s*>\s*\(bn\)/i.test(cols[i])?n*10:n; text=fmtNum(displayN,1)+(isPct?'%':'');
        if((i===4 || isPct) && Number.isFinite(n)){
          if(n>0){text+=(i===4?' <span class="arrow-up">▲</span>':''); if(isPct)cls+=' positive';}
          if(n<0){text+=(i===4?' <span class="arrow-down">▼</span>':''); if(isPct)cls+=' negative';}
        }
      }
      if(i===0) text=firstLabel(text,key);
      h+='<td class="'+cls+'">'+text+'</td>';
    });
    h+='</tr>';
  });
  h+='</tbody>';t.innerHTML=h;

  t.querySelectorAll('thead th.sortable').forEach(th=>{
    th.addEventListener('click',()=>{
      const col=Number(th.dataset.col);
      if(st.col===col) st.dir=st.dir==='asc'?'desc':'asc';
      else {st.col=col; st.dir=col===0?'asc':'desc';}
      renderDataTable(id,key);
    });
  });
}
function regionalMapFromBlock(block){
  const result={};
  const data=block&&block.data;
  if(!data)return result;
  Object.keys(data).filter(k=>k!=='columns').forEach(k=>{
    const row=data[k];
    result[row[0]]={
      aum:row[1]===''||row[1]==null?null:Number(row[1]),
      flow:row[2]===''||row[2]==null?null:Number(row[2])
    };
  });
  return result;
}
function previousRegionalMap(){
  const dates=[...new Set([...Object.keys(REGIONAL_BASELINES),...Object.keys(SNAPSHOTS)])]
    .filter(date=>date<tableState.date).sort().reverse();
  for(const date of dates){
    const baseline=REGIONAL_BASELINES[date]&&REGIONAL_BASELINES[date][tableState.period];
    if(baseline)return baseline;
    const block=SNAPSHOTS[date]&&SNAPSHOTS[date].data&&SNAPSHOTS[date].data.regional&&SNAPSHOTS[date].data.regional[tableState.period];
    if(block)return regionalMapFromBlock(block);
  }
  return {};
}
function changeMarkup(current,previous){
  if(!Number.isFinite(current)||!Number.isFinite(previous))return '';
  const delta=current-previous;
  const pct=previous===0?null:(delta/Math.abs(previous))*100;
  const cls=delta>0?'positive':delta<0?'negative':'neutral';
  const signed=value=>(value>0?'+':'')+fmtNum(value,1);
  return `<span class="change-content"><span class="change-value ${cls}">${signed(delta)}</span><span class="change-percent ${cls}">${pct==null?'':signed(pct)+'%'}</span></span>`;
}
function renderRegionalTable(){
  const block=currentTable.data.regional[tableState.period];
  if(!block)return;
  const data=block.data;
  const table=document.getElementById('regionalTable');
  const previous=previousRegionalMap();
  const state=tableSort.regional;
  const rows=Object.keys(data).filter(k=>k!=='columns').sort((a,b)=>Number(a)-Number(b)).map(k=>data[k]);
  const pinned=[];const regular=[];
  rows.forEach(row=>{const label=row[0]||'';(/^(Total|Global inflows|Global outflows)/.test(label)?pinned:regular).push(row);});
  if(state.col!==null&&state.dir){
    const sourceCol=state.col===3?2:state.col;
    regular.sort((a,b)=>compareTableValues(a,b,sourceCol,'regional',state.dir));
  }
  let html='<colgroup><col style="width:25%"><col style="width:17%"><col style="width:20%"><col style="width:17%"><col style="width:21%"></colgroup><thead><tr>';
  const headers=[['区域',0],['资产管理规模（亿美元）',1],['较上期变化',null],['基金流量（百万美元）',3],['较上期变化',null]];
  headers.forEach(([label,col])=>{
    if(col==null){html+=`<th>${label}<span class="change-heading-note">数值 / 百分比</span></th>`;return;}
    const up=state.col===col&&state.dir==='asc'?' active':'';
    const down=state.col===col&&state.dir==='desc'?' active':'';
    html+=`<th class="sortable" data-col="${col}" title="点击排序">${label}<span class="sort"><span class="up${up}">▲</span><span class="down${down}">▼</span></span></th>`;
  });
  html+='</tr></thead><tbody>';
  [...regular,...pinned].forEach(row=>{
    const key=row[0]||'';
    const total=key==='Total';
    const global=/Global inflows|Global outflows/.test(key);
    const aum=row[1]===''||row[1]==null?null:Number(row[1]);
    const flow=row[2]===''||row[2]==null?null:Number(row[2]);
    const prior=previous[key]||{};
    const aumYi=aum==null?null:aum*10;
    const priorAumYi=Number.isFinite(prior.aum)?prior.aum*10:null;
    html+=`<tr class="${total?'total-row ':global?'global-row ':''}">`;
    html+=`<td>${firstLabel(key,'regional')}</td>`;
    html+=`<td class="num">${aumYi==null?'':fmtNum(aumYi,1)}</td>`;
    html+=`<td class="change-cell">${aumYi==null?'':changeMarkup(aumYi,priorAumYi)}</td>`;
    html+=`<td class="num">${flow==null?'':fmtNum(flow,1)}</td>`;
    html+=`<td class="change-cell">${changeMarkup(flow,prior.flow)}</td>`;
    html+='</tr>';
  });
  table.innerHTML=html+'</tbody>';
  table.querySelectorAll('thead th.sortable').forEach(th=>{
    th.addEventListener('click',()=>{
      const col=Number(th.dataset.col);
      if(state.col===col)state.dir=state.dir==='asc'?'desc':'asc';
      else {state.col=col;state.dir=col===0?'asc':'desc';}
      renderRegionalTable();
    });
  });
}
function cnDate(s){const d=new Date(s+'T00:00:00');return `${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日`;}
function periodSub(period,block){const as=block.asOfDate; if(period==='Year to date')return '截止'+cnDate(as); if(period==='Monthly'){const d=new Date(as+'T00:00:00');return `${d.getFullYear()}年${d.getMonth()+1}月`;} if(period==='Quarterly'){const m=new Date(as+'T00:00:00').getMonth()+1,q=Math.floor((m-1)/3)+1;return `${new Date(as+'T00:00:00').getFullYear()}年第${['一','二','三','四'][q-1]}季度`;}
  const mt=(block.periodTitle||'').match(/Week\s+(\d+)/i);return `截止于${cnDate(as)}的第${mt?mt[1]:''}周`;
}
function renderTables(){
  renderRegionalTable();
  ['Year to date','Monthly','Quarterly','Weekly'].forEach(p=>{const block=currentTable.data.regional[p];const el=document.querySelector(`[data-sub="${p}"]`);if(el)el.textContent=periodSub(p,block);});
}
async function loadDate(date){
  const status=document.getElementById('loadStatus');tableState.date=date;
  if(SNAPSHOTS[date]){currentTable=SNAPSHOTS[date];status.textContent='';renderTables();return;}
  status.textContent='正在读取 WGC 历史数据…';
  try{const u=`https://fsapi.gold.org/api/v11/charts/etfv2/revised/archive-tablegroup/all?asOfDate=${date}&break-cache=17Aug26`;const r=await fetch(u);if(!r.ok)throw new Error(r.status);const j=await r.json();currentTable=j.chartData;SNAPSHOTS[date]=currentTable;status.textContent='';renderTables();}
  catch(e){status.textContent='该日期未内置；浏览器未能直接读取 WGC 接口。';}
}
document.getElementById('periodTabs').addEventListener('click',e=>{const x=e.target.closest('.period-tab');if(!x)return;tableState.period=x.dataset.v;document.querySelectorAll('.period-tab').forEach(y=>y.classList.toggle('active',y===x));renderTables();});
// 表格从 2026-08-07 开始记录网站更新，只开放已内置的数据日。
const VALID_DATES=Object.keys(SNAPSHOTS).filter(date=>date>=FIRST_TABLE_UPDATE).sort();
const VALID_DATE_SET=new Set(VALID_DATES);
const DATE_MIN=VALID_DATES[0], DATE_MAX=VALID_DATES[VALID_DATES.length-1];
let calendarView=new Date(tableState.date+'T00:00:00');
function displayDate(s){return s?cnDate(s):'';}
function ymdLocal(y,m,d){return `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;}
function renderCalendar(){
  const y=calendarView.getFullYear(),m=calendarView.getMonth();
  document.getElementById('calendarTitle').textContent=`${y}年${String(m+1).padStart(2,'0')}月`;
  const grid=document.getElementById('calendarGrid');grid.innerHTML='';
  const first=new Date(y,m,1), mondayIndex=(first.getDay()+6)%7;
  const start=new Date(y,m,1-mondayIndex);
  const today=new Date(); const todayStr=ymdLocal(today.getFullYear(),today.getMonth(),today.getDate());
  for(let i=0;i<42;i++){
    const d=new Date(start);d.setDate(start.getDate()+i);
    const ds=ymdLocal(d.getFullYear(),d.getMonth(),d.getDate());
    const b=document.createElement('button');b.type='button';b.className='calendar-day';b.textContent=d.getDate();
    if(d.getMonth()!==m)b.classList.add('outside');
    if(ds===tableState.date)b.classList.add('selected');
    if(ds===todayStr)b.classList.add('today');
    b.disabled=!VALID_DATE_SET.has(ds);
    b.dataset.date=ds;
    if(!b.disabled)b.addEventListener('click',()=>selectCalendarDate(ds));
    grid.appendChild(b);
  }
  const prevMonthEnd=ymdLocal(y,m,0), nextMonthStart=ymdLocal(y,m+1,1);
  document.getElementById('calPrev').disabled=prevMonthEnd<DATE_MIN;
  document.getElementById('calNext').disabled=nextMonthStart>DATE_MAX;
}
function openCalendar(){const pop=document.getElementById('calendarPopover');calendarView=new Date(tableState.date+'T00:00:00');renderCalendar();pop.hidden=false;document.getElementById('asOfDateBtn').setAttribute('aria-expanded','true');}
function closeCalendar(){document.getElementById('calendarPopover').hidden=true;document.getElementById('asOfDateBtn').setAttribute('aria-expanded','false');}
function selectCalendarDate(ds){if(!VALID_DATE_SET.has(ds))return;document.getElementById('asOfDate').value=ds;document.getElementById('asOfDateText').textContent=displayDate(ds);closeCalendar();loadDate(ds);}
document.getElementById('asOfDateBtn').addEventListener('click',e=>{e.stopPropagation();document.getElementById('calendarPopover').hidden?openCalendar():closeCalendar();});
document.getElementById('calPrev').addEventListener('click',e=>{e.stopPropagation();calendarView=new Date(calendarView.getFullYear(),calendarView.getMonth()-1,1);renderCalendar();});
document.getElementById('calNext').addEventListener('click',e=>{e.stopPropagation();calendarView=new Date(calendarView.getFullYear(),calendarView.getMonth()+1,1);renderCalendar();});
document.getElementById('calendarPopover').addEventListener('click',e=>e.stopPropagation());
document.addEventListener('click',closeCalendar);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCalendar();});
document.getElementById('asOfDate').value=tableState.date;document.getElementById('asOfDateText').textContent=displayDate(tableState.date);
bindToggle('flowUnit',flowState,'unit',renderFlow);bindToggle('flowFreq',flowState,'freq',renderFlow);bindToggle('holdUnit',holdState,'unit',renderHold);bindToggle('holdFreq',holdState,'freq',renderHold);
renderFlow();renderHold();renderTables();

function resizeGoldEtfCharts() {
  ['flowChart', 'holdChart'].forEach(function (id) {
    var chart = document.getElementById(id);
    if (chart && chart.data) Plotly.Plots.resize(chart);
  });
}

document.querySelectorAll('[data-page-link="page-2"], [data-page="page-2"]').forEach(function (link) {
  link.addEventListener('click', function () { window.setTimeout(resizeGoldEtfCharts, 100); });
});
window.addEventListener('resize', resizeGoldEtfCharts);
